'use client';

import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { Plus, Edit, Trash2, FolderTree } from 'lucide-react';

interface Category {
  id: string;
  documentId: string;
  name: string;
  slug: string;
  sort_order: number;
  is_visible: boolean;
  parent?: { id: string; name: string } | null;
}

export default function CategoriesPage() {
  const [categories, setCategories] = useState<Category[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // 新增/编辑弹窗状态
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState<Category | null>(null);
  const [formData, setFormData] = useState({
    name: '',
    slug: '',
    sort_order: 0,
    is_visible: true,
    parent: null as string | null,
  });

  const fetchCategories = async () => {
    try {
      setError(null);
      const response = await api.getCategories('?populate=parent&sort=sort_order:asc');

      let categoryList: Category[] = [];
      if (response && typeof response === 'object' && 'data' in response) {
        if (Array.isArray(response.data)) {
          categoryList = response.data as Category[];
        }
      } else if (Array.isArray(response)) {
        categoryList = response as Category[];
      }

      setCategories(categoryList);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : '获取栏目列表失败';
      console.error('❌ 获取栏目失败', err);
      setError(message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCategories();
  }, []);

  const openModal = (category: Category | null = null) => {
    if (category) {
      setEditingCategory(category);
      setFormData({
        name: category.name,
        slug: category.slug,
        sort_order: category.sort_order,
        is_visible: category.is_visible,
        parent: category.parent?.id || null,
      });
    } else {
      setEditingCategory(null);
      setFormData({ name: '', slug: '', sort_order: 0, is_visible: true, parent: null });
    }
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingCategory(null);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      if (editingCategory) {
        // 编辑
        await api.updateCategory(editingCategory.documentId, formData);
        alert('栏目更新成功');
      } else {
        // 新增
        await api.createCategory(formData);
        alert('栏目创建成功');
      }
      closeModal();
      fetchCategories();
    } catch (err: unknown) {
      alert('操作失败，请检查控制台');
      console.error(err);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('确定删除该栏目吗？（子栏目不会自动删除）')) return;
    try {
      await api.deleteCategory(id);
      alert('删除成功');
      fetchCategories();
    } catch (err) {
      alert('删除失败');
      console.error(err);
    }
  };

  return (
    <div className="space-y-6">
      {/* 标题 + 操作按钮 */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900 flex items-center gap-2">
            <FolderTree className="w-8 h-8" />
            栏目管理
          </h1>
          <p className="text-gray-500 mt-1">共 {categories.length} 个栏目</p>
        </div>
        <button
          onClick={() => openModal()}
          className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-2xl font-medium transition-all"
        >
          <Plus className="w-5 h-5" />
          新增栏目
        </button>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-600 px-6 py-4 rounded-2xl">
          {error}
        </div>
      )}

      {/* 列表 */}
      {loading ? (
        <div className="text-center py-12 text-gray-400">加载中...</div>
      ) : (
        <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
          <table className="w-full">
            <thead className="bg-gray-50 border-b">
              <tr>
                <th className="px-6 py-4 text-left text-sm font-medium text-gray-500">栏目名称</th>
                <th className="px-6 py-4 text-left text-sm font-medium text-gray-500">Slug</th>
                <th className="px-6 py-4 text-left text-sm font-medium text-gray-500">排序</th>
                <th className="px-6 py-4 text-left text-sm font-medium text-gray-500">是否显示</th>
                <th className="px-6 py-4 text-left text-sm font-medium text-gray-500">父栏目</th>
                <th className="px-6 py-4 text-center text-sm font-medium text-gray-500">操作</th>
              </tr>
            </thead>
            <tbody className="divide-y">
              {categories.map((cat) => (
                <tr key={cat.id} className="hover:bg-gray-50 transition-colors">
                  <td className="px-6 py-4 font-medium text-gray-900">{cat.name}</td>
                  <td className="px-6 py-4 text-sm text-gray-500">{cat.slug}</td>
                  <td className="px-6 py-4 text-sm text-gray-500">{cat.sort_order}</td>
                  <td className="px-6 py-4">
                    <span className={`inline-block px-3 py-1 rounded-full text-xs font-medium ${cat.is_visible ? 'bg-emerald-100 text-emerald-600' : 'bg-gray-100 text-gray-600'}`}>
                      {cat.is_visible ? '显示' : '隐藏'}
                    </span>
                  </td>
                  <td className="px-6 py-4 text-sm text-gray-500">
                    {cat.parent?.name || '顶级栏目'}
                  </td>
                  <td className="px-6 py-4 text-center">
                    <div className="flex items-center justify-center gap-3">
                      <button
                        onClick={() => openModal(cat)}
                        className="text-blue-600 hover:text-blue-700"
                      >
                        <Edit className="w-5 h-5" />
                      </button>
                      <button
                        onClick={() => handleDelete(cat.documentId)}
                        className="text-red-500 hover:text-red-600"
                      >
                        <Trash2 className="w-5 h-5" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* 新增/编辑弹窗 */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg mx-4">
            <div className="px-8 pt-6 pb-4 border-b">
              <h2 className="text-2xl font-bold">
                {editingCategory ? '编辑栏目' : '新增栏目'}
              </h2>
            </div>

            <form onSubmit={handleSubmit} className="p-8 space-y-6">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">栏目名称</label>
                <input
                  type="text"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  className="w-full px-5 py-4 border border-gray-200 rounded-2xl focus:outline-none focus:border-blue-500"
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Slug（唯一标识）</label>
                <input
                  type="text"
                  value={formData.slug}
                  onChange={(e) => setFormData({ ...formData, slug: e.target.value })}
                  className="w-full px-5 py-4 border border-gray-200 rounded-2xl focus:outline-none focus:border-blue-500"
                  required
                />
              </div>

              <div className="grid grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">排序值</label>
                  <input
                    type="number"
                    value={formData.sort_order}
                    onChange={(e) => setFormData({ ...formData, sort_order: parseInt(e.target.value) || 0 })}
                    className="w-full px-5 py-4 border border-gray-200 rounded-2xl focus:outline-none focus:border-blue-500"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">是否显示</label>
                  <label className="flex items-center gap-2">
                    <input
                      type="checkbox"
                      checked={formData.is_visible}
                      onChange={(e) => setFormData({ ...formData, is_visible: e.target.checked })}
                      className="w-5 h-5 text-blue-600"
                    />
                    <span className="text-gray-700">在前端显示</span>
                  </label>
                </div>
              </div>

              <div className="flex justify-end gap-4 pt-4">
                <button
                  type="button"
                  onClick={closeModal}
                  className="px-8 py-4 text-gray-500 hover:text-gray-700 font-medium"
                >
                  取消
                </button>
                <button
                  type="submit"
                  className="px-8 py-4 bg-blue-600 hover:bg-blue-700 text-white font-medium rounded-2xl"
                >
                  {editingCategory ? '保存修改' : '创建栏目'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
